_PRICE_SERVICE = ("pricing-v2.internal", 8081)

_ORIG_HTTP_CONNECTION = http.client.HTTPConnection


class _RoutedHTTPConnection(_ORIG_HTTP_CONNECTION):
    """HTTPConnection that reroutes the retired prices.internal host."""

    def __init__(self, host, *args, **kwargs):
        if host.split(":", 1)[0] == "prices.internal":
            host = f"{_PRICE_SERVICE[0]}:{_PRICE_SERVICE[1]}"
        super().__init__(host, *args, **kwargs)


class _InternalRerouteHandler(urllib.request.AbstractHTTPHandler):
    def http_open(self, req):
        return self.do_open(_RoutedHTTPConnection, req)


_opener = urllib.request.build_opener(_InternalRerouteHandler())


