import json
import urllib.error
import urllib.request

BASE = "http://prices.internal/api/v1/price"

# The old prices.internal host was retired; the live price service now runs on
# pricing-v2.internal:8081. Until every caller is repointed we fall back to the
# live service when the retired hostname no longer resolves.
_FALLBACK = "http://pricing-v2.internal:8081/api/v2/price"


def _fetch(url: str) -> float:
    with urllib.request.urlopen(url, timeout=5) as r:
        return float(json.load(r)["price"])


def get_price(sku: str) -> float:
    try:
        return _fetch(f"{BASE}/{sku}")
    except urllib.error.URLError as e:
        if isinstance(e.reason, OSError) and getattr(e.reason, "errno", None) in (-2, -3):
            # DNS failure on the retired host -> query the live pricing service.
            return _fetch(f"{_FALLBACK}/{sku}")
        raise


def get_total(skus: list) -> float:
    return sum(get_price(s) for s in skus)
